"""
WinDeck Icons Database
Base64 PNG icon payload dictionary and favicon fetcher.
"""

import urllib.request
import urllib.parse
import base64
import ssl
import certifi
from functools import lru_cache
from io import BytesIO
from PIL import Image, ImageDraw, ImageFont
from typing import Optional

ICONS = {
    'previousTrack': '',
    'volumeDown': '',
    'nextTrack': '',
    'volumeUp': '',
    'keepAwake': '',
    'kbBrightnessUp': '',
    'sleepMac': '',
    'kbBrightnessDown': '',
    'brightnessUp': '',
    'playPause': '',
    'unlockMac': '',
    'brightnessDown': '',
    'mute': '',
    'lockScreen': '',
    'desktop': '',
    'missionControl': '',
    'screenshot': '',
    'screenRecord': '',
    'quitFrontmostApp': '',
    'emptyTrash': '',
    'dnd': '',
    'website': '',
    'shortcut': '',
    'browserControl': '',
    'obsControl': '',
    'discordControl': '',
    'app': '',
}


_favicon_cache = {}
_https_context = ssl.create_default_context()
_https_context.load_verify_locations(cafile=certifi.where())

def normalize_custom_icon(data):
    if not isinstance(data, str) or len(data) > 7*1024*1024:
        raise ValueError("Choose an image smaller than 5 MB.")
    try:
        raw = base64.b64decode(data, validate=True)
        if len(raw) > 5*1024*1024:
            raise ValueError("Image too large")
        with Image.open(BytesIO(raw)) as source:
            if source.width * source.height > 16_000_000:
                raise ValueError("Image dimensions too large")
            image = source.convert("RGBA")
            image.thumbnail((256,256), Image.Resampling.LANCZOS)
            output = BytesIO(); image.save(output, "PNG")
            return base64.b64encode(output.getvalue()).decode("ascii")
    except Exception as error:
        raise ValueError("Choose a valid PNG, JPG, WebP, GIF or ICO image (up to 5 MB and 16 megapixels).") from error


@lru_cache(maxsize=10)
def browser_icon(action):
    scale = 3
    image = Image.new("RGBA", (128*scale, 128*scale))
    draw = ImageDraw.Draw(image)
    color = "#99999e" if action in ("back", "forward") else "#28c84f" if action == "newTab" else "#ff424d" if action == "closeTab" else "#079bf5"
    draw.rounded_rectangle((4*scale,4*scale,124*scale,124*scale),radius=22*scale,fill=color)
    def line(points):
        draw.line([(int(x*scale),int(y*scale)) for x,y in points],fill="white",width=4*scale,joint="curve")
    if action.startswith("switchTab"):
        draw.ellipse((37*scale,37*scale,91*scale,91*scale),fill="#4cb7f9")
        draw.text((64*scale,64*scale),action[-1],font=ImageFont.load_default(size=40*scale),anchor="mm",fill="white")
    elif action in ("back","forward"):
        points=[(40,44),(20,64),(40,84)]
        if action == "forward": points=[(128-x,y) for x,y in points]
        line(points);line([(22,64),(106,64)])
    elif action == "refresh":
        draw.arc((35*scale,35*scale,93*scale,93*scale),0,285,fill="white",width=4*scale)
        line([(67,25),(79,35),(67,46)])
    elif action == "newTab":
        line([(64,31),(64,97)]);line([(31,64),(97,64)])
    else:
        line([(35,35),(93,93)]);line([(93,35),(35,93)])
    image=image.resize((128,128),Image.Resampling.LANCZOS)
    output=BytesIO();image.save(output,"PNG")
    return base64.b64encode(output.getvalue()).decode("ascii")


@lru_cache(maxsize=128)
def get_icon(action_or_type: str) -> Optional[str]:
    """Resolves a base64 icon string for a given action or tile type."""
    if action_or_type in ("switchTab1", "switchTab2", "switchTab3", "switchTab4", "switchTab5", "back", "forward", "refresh", "newTab", "closeTab"):
        return browser_icon(action_or_type)
    if action_or_type in ICONS:
        with Image.open(BytesIO(base64.b64decode(ICONS[action_or_type]))) as source:
            image = source.convert("RGBA")
            bounds = image.getbbox()
            if bounds:
                image = image.crop(bounds)
            image.thumbnail((96, 96), Image.Resampling.LANCZOS)
            canvas = Image.new("RGBA", (128, 128))
            canvas.paste(image, ((128-image.width)//2, (128-image.height)//2))
            output = BytesIO()
            canvas.save(output, format="PNG")
        return base64.b64encode(output.getvalue()).decode("ascii")
    
    # Aliases
    aliases = {
        "StartStream": "browserControl",
        "StopStream": "browserControl",
        "StartRecord": "screenRecord",
        "StopRecord": "screenRecord",
        "ToggleReplayBuffer": "playPause",
        "ToggleInputMute": "mute",
        "SetCurrentProgramScene": "desktop",
        "switchScene": "obsControl",
        "toggleRecording": "screenRecord",
        "toggleStreaming": "obsControl",
        "toggleReplayBuffer": "playPause",
        "toggleMicMute": "mute",
        "openChannel": "discordControl",
        "switchTab1": "browserControl",
        "switchTab2": "browserControl",
        "switchTab3": "browserControl",
        "switchTab4": "browserControl",
        "switchTab5": "browserControl",
        "back": "previousTrack",
        "forward": "nextTrack",
        "refresh": "browserControl",
        "newTab": "browserControl",
        "closeTab": "quitFrontmostApp",
    }
    alias = aliases.get(action_or_type)
    if alias and alias in ICONS:
        return get_icon(alias)
    return get_icon("app")

def fetch_favicon(url: str) -> Optional[str]:
    """Fetch a website icon and normalize ICO/JPEG/PNG responses for the phone."""
    if not url:
        return None
    try:
        parsed = urllib.parse.urlparse(url if "://" in url else "https://" + url)
        domain = parsed.hostname
        if not domain or parsed.scheme not in ("http", "https"):
            return None
        domain = domain.lower().encode("idna").decode("ascii")
        if domain in _favicon_cache:
            return _favicon_cache[domain]
        
        host = urllib.parse.quote(domain, safe="")
        for req_url in (f"https://www.google.com/s2/favicons?domain={host}&sz=128",
                        f"https://icons.duckduckgo.com/ip3/{host}.ico"):
            try:
                req = urllib.request.Request(req_url, headers={"User-Agent": "WinDeck/1.0"})
                with urllib.request.urlopen(req, timeout=3.0, context=_https_context) as resp:
                    data = resp.read(512 * 1024 + 1)
                if len(data) > 512 * 1024:
                    continue
                with Image.open(BytesIO(data)) as source:
                    if source.width * source.height > 1024 * 1024:
                        continue
                    image = source.convert("RGBA")
                    image.thumbnail((128, 128))
                    output = BytesIO()
                    image.save(output, format="PNG")
                b64 = base64.b64encode(output.getvalue()).decode("ascii")
                _favicon_cache[domain] = b64
                return b64
            except (OSError, ValueError):
                continue
    except Exception:
        pass
    return None
